# Optimized RoPE kernel
rope_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rope_kernel(
    const float* q_in,
    const float* k_in,
    const float* cos,
    const float* sin,
    float* q_out,
    float* k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim,
    int rope_dim
) {
    int batch = blockIdx.x;
    int head = blockIdx.y;
    int seq = blockIdx.z * blockDim.x + threadIdx.x;

    if (seq >= seq_len) return;

    int out_idx = ((batch * num_heads + head) * seq_len + seq) * head_dim;
    int cos_idx = seq * rope_dim;

    // Apply to last rope_dim elements
    for (int i = 0; i < rope_dim / 2; i++) {
        int idx = out_idx + head_dim - rope_dim + i * 2;
        int offset = i * 2;

        float q_x1 = q_in[idx];
        float q_x2 = q_in[idx + 1];
        float c = cos[cos_idx + offset];
        float s = sin[cos_idx + offset];

        q_out[idx] = q_x1 * c - q_x2 * s;
        q_out[idx + 1] = q_x1 * s + q_x2 * c;

        float k_x1 = k_in[idx];
        float k_x2 = k_in[idx + 1];

        k_out[idx] = k_x1 * c - k_x2 * s;
        k_out[idx + 1] = k_x1 * s + k_x2 * c;
    }

    // Copy non-rope dimensions
    for (int i = 0; i < head_dim - rope_dim; i++) {
        q_out[out_idx + i] = q_in[out_idx + i];
        k_out[out_idx + i] = k_in[out_idx + i];
    }
}

std::vector<torch::Tensor> rope_forward(
    torch::Tensor q, torch::Tensor k, torch::Tensor cos, torch::Tensor sin,
    int rope_dim
) {
    int batch_size = q.size(0);
    int num_heads = q.size(1);
    int seq_len = q.size(2);
    int head_dim = q.size(3);

    auto q_out = torch::zeros_like(q);
    auto k_out = torch::zeros_like(k);

    const int block_size = 256;
    dim3 grid(batch_size, num_heads, (seq_len + block_size - 1) / block_size);

    hipLaunchKernelGGL(
        rope_kernel,
        grid,
        block_size,
        0, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size, num_heads, seq_len, head_dim, rope_dim
    );

    return {q_out, k_out};
}
"""

