class DeepSeekRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class DeepSeekRotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=2048, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos(), emb.sin()


class ModelNew(nn.Module):
    """
    DeepSeek-V3 Multi-head Latent Attention (MLA) - Optimized with HIP kernels
    """

    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        # Query projection with LoRA compression
        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNorm(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        # KV projection with LoRA compression
        self.kv_a_proj_with_mqa = nn.Linear(
            hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False
        )
        self.kv_a_layernorm = DeepSeekRMSNorm(kv_lora_rank)
        self.kv_b_proj = nn.Linear(
            kv_lora_rank,
            num_attention_heads * (qk_nope_head_dim + self.v_head_dim),
            bias=False,
        )

        # Output projection
        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = DeepSeekRotaryEmbedding(
            qk_rope_head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        # Custom kernels
        self.fused_rmsnorm_linear_q = fused_rmsnorm_linear_q
        self.fused_rmsnorm_linear_kv = fused_rmsnorm_linear_kv
        self.rope_module = rope_module

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Query projection with LoRA compression - use standard ops for simplicity
        q = self.q_b_proj(self.q_a_layernorm(self.q_a_proj(hidden_states)))
        q = q.view(bsz, q_len, self.num_heads, self.q_head_dim).transpose(1, 2)

        # Split query into nope (non-positional) and rope (positional) components
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        # KV projection with compression
        compressed_kv = self.kv_a_proj_with_mqa(hidden_states)
        compressed_kv, k_pe = torch.split(
            compressed_kv, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1
        )
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim).transpose(1, 2)

        # Expand compressed KV
        kv = self.kv_b_proj(self.kv_a_layernorm(compressed_kv))
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim)
        kv = kv.transpose(1, 2)

        k_nope, value_states = torch.split(kv, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        # Apply rotary embeddings to positional components only
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        q_pe, k_pe = apply_rotary_pos_emb(q_pe, k_pe, cos, sin)

        # Assemble full query and key states
        query_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim,
                                   device=hidden_states.device, dtype=hidden_states.dtype)
        query_states[:, :, :, :self.qk_nope_head_dim] = q_nope
        query_states[:, :, :, self.qk_nope_head_dim:] = q_pe

        key_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim,
                                 device=hidden_states.device, dtype=hidden_states.dtype)
        key_states[:, :, :, :self.qk_nope_head_dim] = k_nope
        key_states[:, :, :, self.qk_rope_head_dim:] = k_pe

        # Compute attention
        attn_weights = torch.matmul(query_states, key_states.transpose(2, 3)) * self.softmax_scale

        # Apply causal mask
        causal_mask = torch.triu(
            torch.ones(q_len, q_len, device=hidden_states.device, dtype=torch.bool),
            diagonal=1
        )
        attn_weights = attn_weights.masked_fill(causal_mask, float('-inf'))

        attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query_states.dtype)
        attn_weights = F.dropout(attn_weights, p=self.attention_dropout, training=self.training)

        attn_output = torch.matmul(attn_weights, value_states)
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused kernel for Kimi Delta Attention timestep computation
# This kernel fuses multiple operations from the recurrence loop:
# 1. S @ k (matrix-vector multiplication)
# 2. error = S_k - v
# 3. outer product error @ k^T
# 4. diagonal gating diag(a) @ S
# 5. state update S = S_gated - beta * error_outer_k
# 6. output computation o = S @ q

kimi_delta_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_SIZE 16
#define MAX_HEAD_DIM 128

// Fused kernel for one timestep of KDA recurrence
// Input shapes:
//   S:    [batch, num_heads, head_dim_v, head_dim_qk]
//   k_t:  [batch, num_heads, head_dim_qk]
//   v_t:  [batch, num_heads, head_dim_v]
//   a_t:  [batch, num_heads, head_dim_v]
//   q_t:  [batch, num_heads, head_dim_qk]
//   beta: [batch, num_heads]
// Output:
//   S_out: [batch, num_heads, head_dim_v, head_dim_qk]
//   o_t:   [batch, num_heads, head_dim_v]

__global__ void kimi_delta_timestep_kernel(
    const float* __restrict__ S,
    const float* __restrict__ k_t,
    const float* __restrict__ v_t,
    const float* __restrict__ a_t,
    const float* __restrict__ q_t,
    const float* __restrict__ beta,
    float* __restrict__ S_out,
    float* __restrict__ o_t,
    int batch_size, int num_heads,
    int head_dim_v, int head_dim_qk
) {
    int batch = blockIdx.z;
    int head = blockIdx.y;

    // Each (row, col) of the matrix is processed
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y2 * blockDim.y + threadIdx.y;  // y2 is separate dimension

    if (row >= head_dim_v || blockIdx.y2 * blockDim.y + threadIdx.y >= head_dim_qk) {
        return;
    }

    // Base indices for this batch and head
    int S_base = (batch * num_heads + head) * head_dim_v * head_dim_qk;
    int k_base = (batch * num_heads + head) * head_dim_qk;
    int v_base = (batch * num_heads + head) * head_dim_v;
    int a_base = (batch * num_heads + head) * head_dim_v;
    int q_base = (batch * num_heads + head) * head_dim_qk;
    int beta_idx = batch * num_heads + head;

    int S_out_base = S_base;
    int o_t_base = (batch * num_heads + head) * head_dim_v;

    // Compute S @ k and output at same time
    float S_k_val = 0.0f;
    float S_q_val = 0.0f;
    float S_val = S[S_base + row * head_dim_qk + col];

    // Compute dot products for this row
    #pragma unroll
    for (int k = 0; k < head_dim_qk; k++) {
        float k_val = k_t[k_base + k];
        float q_val = q_t[q_base + k];
        S_k_val += S[S_base + row * head_dim_qk + k] * k_val;
        S_q_val += S[S_base + row * head_dim_qk + k] * q_val;
    }

    // Error: S_k - v
    float error = S_k_val - v_t[v_base + row];

    // Get current values
    float a_val = a_t[a_base + row];
    float beta_val = beta[beta_idx];
    float k_col_val = k_t[k_base + col];

    // Apply diagonal gating: diag(a) @ S
    float S_gated = a_val * S_val;

    // Outer product contribution: beta * error * k^T
    float outer_prod = beta_val * error * k_col_val;

    // State update
    float S_new = S_gated - outer_prod;

    // Write outputs
    S_out[S_out_base + row * head_dim_qk + col] = S_new;

    // Output computation (only write for col=0 since we computed full dot product)
    if (threadIdx.y == 0 && col == 0) {
        // Compute full S @ q output
        #pragma unroll
        for (int r = 0; r < head_dim_v; r++) {
            float S_q_dot = 0.0f;
            #pragma unroll
            for (int k = 0; k < head_dim_qk; k++) {
                S_q_dot += S[S_base + r * head_dim_qk + k] * q_t[q_base + k];
            }
            o_t[o_t_base + r] = S_q_dot;
        }
    }
}

// Simpler per-row kernel: each thread handles one row of S
__global__ void kimi_delta_fused_kernel(
    const float* __restrict__ S,
    const float* __restrict__ k_t,
    const float* __restrict__ v_t,
    const float* __restrict__ a_t,
    const float* __restrict__ q_t,
    const float* __restrict__ beta,
    float* __restrict__ S_out,
    float* __restrict__ o_t,
    int batch_size, int num_heads,
    int head_dim_v, int head_dim_qk
) {
    int batch = blockIdx.x;  // batch
    int head = blockIdx.y;   // head
    int row = blockIdx.z * blockDim.z + threadIdx.z;  // row in head_dim_v

    if (batch >= batch_size || head >= num_heads || row >= head_dim_v) {
        return;
    }

    // Base indices
    int S_base = (batch * num_heads + head) * head_dim_v * head_dim_qk;
    int k_base = (batch * num_heads + head) * head_dim_qk;
    int v_base = (batch * num_heads + head) * head_dim_v;
    int a_base = (batch * num_heads + head) * head_dim_v;
    int q_base = (batch * num_heads + head) * head_dim_qk;
    int beta_idx = batch * num_heads + head;
    int S_out_base = S_base;
    int o_t_base = (batch * num_heads + head) * head_dim_v;

    float a_val = a_t[a_base + row];
    float v_val = v_t[v_base + row];
    float beta_val = beta[beta_idx];

    // Compute S @ k for this row (dot product along k dimension)
    float S_k_val = 0.0f;
    #pragma unroll
    for (int k = 0; k < head_dim_qk; k++) {
        S_k_val += S[S_base + row * head_dim_qk + k] * k_t[k_base + k];
    }

    float error = S_k_val - v_val;

    // Update each column of S for this row
    #pragma unroll
    for (int col = 0; col < head_dim_qk; col++) {
        float S_val = S[S_base + row * head_dim_qk + col];
        float S_gated = a_val * S_val;
        float outer_prod = beta_val * error * k_t[k_base + col];
        float S_new = S_gated - outer_prod;
        S_out[S_out_base + row * head_dim_qk + col] = S_new;
    }

    // Compute output: S_new @ q for this row
    float o_val = 0.0f;
    #pragma unroll
    for (int k = 0; k < head_dim_qk; k++) {
        o_val += S_out[S_out_base + row * head_dim_qk + k] * q_t[q_base + k];
    }
    o_t[o_t_base + row] = o_val;
}

torch::Tensor kimi_delta_fused_hip(
    torch::Tensor S, torch::Tensor k_t, torch::Tensor v_t,
    torch::Tensor a_t, torch::Tensor q_t, torch::Tensor beta
) {
    int batch_size = S.size(0);
    int num_heads = S.size(1);
    int head_dim_v = S.size(2);
    int head_dim_qk = S.size(3);

    auto S_out = torch::zeros_like(S);
    auto o_t = torch::zeros({batch_size, num_heads, head_dim_v}, S.options());

    int thread_per_block = 256;
    dim3 blockDim(thread_per_block);
    dim3 gridDim(batch_size, num_heads, (head_dim_v + thread_per_block - 1) / thread_per_block);

    kimi_delta_fused_kernel<<<gridDim, blockDim, 0, at::cuda::getCurrentCUDAStream()>>>(
        S.data_ptr<float>(), k_t.data_ptr<float>(), v_t.data_ptr<float>(),
        a_t.data_ptr<float>(), q_t.data_ptr<float>(), beta.data_ptr<float>(),
        S_out.data_ptr<float>(), o_t.data_ptr<float>(),
        batch_size, num_heads, head_dim_v, head_dim_qk
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        AT_ERROR("HIP kernel launch failed: ", hipGetErrorString(err));
    }

    return o_t;
}
"""

kimi_delta_module = load_inline(
    name="kimi_delta",
