#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void int4_quantized_gemm_kernel(
    const half* __restrict__ x,
    const uint8_t* __restrict__ weight_packed,
    const half* __restrict__ scales,
    half* __restrict__ output,
    int M,
    int N,
    int K,
    int group_size
) {
    // K is input features, but packed weights are stored as (N, K/2)
    // Each group of group_size weights shares one scale

    int n = blockIdx.x * blockDim.x + threadIdx.x;
    int m = blockIdx.y * blockDim.y + threadIdx.y;

    if (n >= N || m >= M) return;

    // Compute number of groups in K dimension
    int num_groups = K / group_size;

    // Compute dot product
    float acc = 0.0f;

    for (int k = 0; k < K; k++) {
        // Get input value
        float x_val = __half2float(x[m * K + k]);

        // Get packed weight - weights stored as (N, K/2)
        int packed_idx = n * (K / 2) + (k / 2);
        uint8_t packed = weight_packed[packed_idx];

        // Extract low or high nibble based on k parity
        int w_int;
        if (k % 2 == 0) {
            w_int = packed & 0x0F;  // Low nibble (first weight)
        } else {
            w_int = (packed >> 4) & 0x0F;  // High nibble (second weight)
        }

        // Get scale for this group
        int group_idx = k / group_size;
        float scale = __half2float(scales[n * num_groups + group_idx]);

        // Dequantize and accumulate
        // Dequant formula: scale * (w_int - 8)
        acc += x_val * scale * ((float)(w_int) - 8.0f);
    }

    output[m * N + n] = __float2half(acc);
}

