# Fused Gated Dual GEMM kernel
# Computes: output = down_proj(SiLU(gate_proj(x)) * up_proj(x))
# This reads x once and computes all projections and activations in a single kernel

gateld_gemm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gated_dual_gemm_kernel(
    const float* x,          // (num_tokens, hidden_size)
    const float* gate_proj,  // (intermediate_size, hidden_size)
    const float* up_proj,    // (intermediate_size, hidden_size)
    const float* down_proj,  // (hidden_size, intermediate_size)
    float* output,           // (num_tokens, hidden_size)
    int num_tokens,
    int hidden_size,
    int intermediate_size
) {
    // Each thread block processes one token, computing all outputs for that token
    int token_idx = blockIdx.x;
    if (token_idx >= num_tokens) return;

    // Use shared memory for intermediate results
    // Size: intermediate_size
    extern __shared__ float shared_mem[];
    float* gate = shared_mem;      // Size: intermediate_size
    float* up = gate + intermediate_size; // Size: intermediate_size (when needed)

    // First compute gate_proj and up_proj (read x once)
    // Each thread computes dot product for one intermediate dimension
    int im_idx = threadIdx.x;
    if (im_idx < intermediate_size) {
        float gate_sum = 0.0f;
        float up_sum = 0.0f;

        const float* x_token = x + token_idx * hidden_size;
        const float* gate_w = gate_proj + im_idx * hidden_size;
        const float* up_w = up_proj + im_idx * hidden_size;

        // Unroll the loop for better performance
        for (int i = 0; i < hidden_size; i++) {
            float x_val = x_token[i];
            gate_sum += x_val * gate_w[i];
            up_sum += x_val * up_w[i];
        }

        // Store intermediate results
        gate[im_idx] = gate_sum;
        up[im_idx] = up_sum;
    }

    __syncthreads();

    // Compute output: down_proj(SiLU(gate) * up)
    // Each thread computes one output dimension
    int out_idx = threadIdx.x;
    if (out_idx < hidden_size) {
        const float* down_w = down_proj + out_idx * intermediate_size;
        float result = 0.0f;

        for (int i = 0; i < intermediate_size; i++) {
            // SiLU activation: gate * sigmoid(gate) = gate / (1 + exp(-gate))
            float g = gate[i];
            float silu_g = g * (1.0f / (1.0f + expf(-g)));
            float u = up[i];

            // Element-wise multiply then multiply with down weight
            result += silu_g * u * down_w[i];
        }

        output[token_idx * hidden_size + out_idx] = result;
    }
}

torch::Tensor gated_dual_gemm_hip(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj
) {
    int num_tokens = x.size(0);
    int hidden_size = x.size(1);
    int intermediate_size = gate_proj.size(0);

    auto output = torch::zeros_like(x);

    // We need enough threads for both intermediate_size and hidden_size (whichever is larger)
    int max_size = (intermediate_size > hidden_size) ? intermediate_size : hidden_size;
    int block_size = max_size;

    // Shared memory for gate and up (intermediate_size * 2)
    int shared_mem_size = intermediate_size * 2 * sizeof(float);

    gated_dual_gemm_kernel<<<num_tokens, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        hidden_size,
        intermediate_size
    );

    return output;
}
"""

gated_dual_gemm = load_inline(
    name="gated_dual_gemm",
    cpp_sources=gateld_gemm_cpp_source,
