# Optimized RoPE kernel
rope_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void rope_forward_kernel(
    const float* q,
    const float* k,
    const float* cos,
    const float* sin,
    float* q_out,
    float* k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim,
    int rope_dim
) {
    int b = blockIdx.x;
    int h = blockIdx.y;
    int seq = blockIdx.z * blockDim.x + threadIdx.x;

    if (seq >= seq_len) return;

    int base_idx = ((b * num_heads + h) * seq_len + seq) * head_dim;
    int cos_idx = seq * (rope_dim / 2);

    // Copy non-rope dimensions (nope head dims)
    int nope_dim = head_dim - rope_dim;
    for (int i = 0; i < nope_dim; i += 1) {
        int idx = base_idx + i;
        if (idx < base_idx + head_dim) {
            q_out[idx] = q[idx];
            k_out[idx] = k[idx];
        }
    }

    // Apply rope to rope dimensions
    for (int i = 0; i < rope_dim / 2; i++) {
        int idx = base_idx + nope_dim + i * 2;
        int c_idx = cos_idx + i;

        if (idx + 1 < base_idx + head_dim) {
            float q_x1 = q[idx];
            float q_x2 = q[idx + 1];
            float k_x1 = k[idx];
            float k_x2 = k[idx + 1];
            float c = cos[c_idx];
            float s = sin[c_idx];

            q_out[idx] = q_x1 * c - q_x2 * s;
            q_out[idx + 1] = q_x1 * s + q_x2 * c;
            k_out[idx] = k_x1 * c - k_x2 * s;
            k_out[idx + 1] = k_x1 * s + k_x2 * c;
        }
    }
}

std::vector<torch::Tensor> rope_forward(
    torch::Tensor q, 
    torch::Tensor k, 
    torch::Tensor cos, 
    torch::Tensor sin,
    int rope_dim
) {
    int batch_size = q.size(0);
    int num_heads = q.size(1);
    int seq_len = q.size(2);
    int head_dim = q.size(3);

    auto q_out = torch::zeros_like(q);
    auto k_out = torch::zeros_like(k);

    dim3 grid(batch_size, num_heads, (seq_len + 255) / 256);
    int block_size = 256;

    hipLaunchKernelGGL(
        rope_forward_kernel,
