        block_size,
        0, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size, num_heads, seq_len, head_dim, rope_dim
    );

