class ModelNew(nn.Module):
    """
    Optimized FP8-like Matrix Multipulation using custom HIP kernels.

    This implementation:
    1. Computes quantization scales in parallel
    2. Uses fused quantization + matmul kernel
    3. Shared memory tiling for performance
    4. Works on MI300x hardware without _scaled_mm
    """

    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        # Load custom kernels
        self.compute_scale = optimized_matmul.compute_scale_hip
        self.quantized_matmul = optimized_matmul.quantized_matmul_hip

        # FP8 format specifications
        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        # Weight matrix
        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Optimized FP8 matmul using custom HIP kernels.

        Input x: (batch, seq_len, K) 
        Weight: (K, N)
        Output: (batch, seq_len, N)
        """
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        # Convert to FP32 for computation
        x_2d = x.view(-1, self.K).float()
        w = self.weight.float()

        M_total = x_2d.shape[0]

        # Compute scales using parallel reduction kernel
        scale_a_tensor = self.compute_scale(x_2d, self.fp8_max)
        scale_b_tensor = self.compute_scale(w, self.fp8_max)

        # Use fused quantized matmul kernel
        out = self.quantized_matmul(
            x_2d,
            w,
            scale_a_tensor,
            scale_b_tensor,
            self.fp8_max,
            M_total,
            self.K,
            self.N
        )

        return out.view(batch_size, seq_len, self.N).to(input_dtype)

