    if (inter_elem < intermediate_size) {
        float gate_val = 0.0f;
        float up_val = 0.0f;
        for (int i = 0; i < hidden_size; i++) {
            gate_val += shared_gate[inter_elem * hidden_size + i] * input_ptr[i];
            up_val += shared_up[inter_elem * hidden_size + i] * input_ptr[i];
        }
        shared_intermediate[inter_elem] = silu(gate_val) * up_val;
    }

    __syncthreads();

    // Each thread computes one output element
    int out_elem = tx;
    if (out_elem < hidden_size) {
        float down_sum = 0.0f;
        for (int i = 0; i < intermediate_size; i++) {
            down_sum += shared_down[out_elem * intermediate_size + i] * shared_intermediate[i];
        }

        // Atomic add to output (redundant since each token has unique token_idx, 
        // but we need to accumulate across expert_rank)
        int out_idx = token_idx * hidden_size + out_elem;
        atomicAdd(&output[out_idx], down_sum * weight);
    }
}

torch::Tensor fused_expert_mlp_hip(
    torch::Tensor gate_weights,
    torch::Tensor up_weights,
    torch::Tensor down_weights,
    torch::Tensor expanded_tokens,
    torch::Tensor topk_idx_flat,
    torch::Tensor topk_weights,
    int num_tokens_original,
    int top_k
) {
    auto hidden_size = gate_weights.size(2);
    auto intermediate_size = gate_weights.size(1);
    auto n_experts = gate_weights.size(0);

    auto output = torch::zeros({num_tokens_original, hidden_size}, torch::kFloat32).cuda();

    int block_size = 256;
    int num_blocks = topk_idx_flat.size(0);  // num_tokens * top_k

    size_t shared_mem_size = (intermediate_size * hidden_size * 2 +  // gate + up
                             hidden_size * intermediate_size +        // down
                             intermediate_size) * sizeof(float);     // intermediate

    fused_expert_mlp_kernel_v2<<<num_blocks, block_size, shared_mem_size>>>(
        gate_weights.data_ptr<float>(),
        up_weights.data_ptr<float>(),
        down_weights.data_ptr<float>(),
        expanded_tokens.data_ptr<float>(),
        topk_idx_flat.data_ptr<int32_t>(),
        topk_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens_original,
        top_k,
        hidden_size,
        intermediate_size,
        n_experts
    );

    return output;
}
