os.environ["CXX"] = "hipcc"

# CUDA/HIP kernel for GQA attention without explicit KV expansion
gqa_attention_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

// GQA Attention kernel
__global__ void gqa_attention_kernel(
    const float* __restrict__ query,
    const float* __restrict__ key,
    const float* __restrict__ value,
    float* __restrict__ output,
    const int batch_size,
    const int num_heads,
    const int num_kv_heads,
    const int seq_len,
    const int head_dim,
    const int num_key_value_groups,
    const float scale
) {
    extern __shared__ float sdata[];  // Shared memory for query vector

    // Block index maps to (query_head, batch, query_position)
    int block_idx = blockIdx.x;
    int head = block_idx % num_heads;
    int b = (block_idx / num_heads) % batch_size;
    int pos = block_idx / (num_heads * batch_size);

    // KV head corresponding to this query head
    int kv_head = head / num_key_value_groups;

    int tid = threadIdx.x;

    // Load query vector into shared memory
    // Each thread loads one element if head_dim > 128, else multiple
    for (int i = tid; i < head_dim; i += blockDim.x) {
        int query_offset = b * num_heads * seq_len * head_dim + head * seq_len * head_dim + pos * head_dim + i;
        sdata[i] = query[query_offset];
    }
    __syncthreads();

    // Compute attention and output for this query position
    // Each thread handles one dimension of the output
    for (int dim = tid; dim < head_dim; dim += blockDim.x) {
        float sum = 0.0f;

        // Compute attention weights and weighted sum
        for (int k_pos = 0; k_pos < seq_len; k_pos++) {
            // Compute dot product of query and key at position k_pos
            float score = 0.0f;
            for (int i = 0; i < head_dim; i++) {
                int key_offset = b * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + k_pos * head_dim + i;
                score += sdata[i] * key[key_offset];
            }

            // Scale
            score *= scale;

            // Apply causal mask
            if (k_pos > pos) {
                score = -1e20f;
            }

            // Compute softmax weight for this key position
            // We need max and sum across all positions
            float max_score = score;
            float exp_sum = 0.0f;

            // First pass: find max
            for (int j = 0; j < seq_len; j++) {
                int j_key_offset = b * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + j * head_dim;
                float s_j = 0.0f;
                for (int i = 0; i < head_dim; i++) {
                    s_j += sdata[i] * key[j_key_offset + i];
                }
                s_j *= scale;
                if (j > pos) {
                    s_j = -1e20f;
                }
                if (s_j > max_score) max_score = s_j;
            }

            // Second pass: compute exp and sum
            float attn_weight = 0.0f;
            for (int j = 0; j < seq_len; j++) {
                int j_key_offset = b * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + j * head_dim;
                float s_j = 0.0f;
                for (int i = 0; i < head_dim; i++) {
                    s_j += sdata[i] * key[j_key_offset + i];
                }
                s_j *= scale;
                if (j > pos) {
                    s_j = -1e20f;
                }
                if (j == k_pos) {
                    attn_weight = expf(s_j - max_score);
                }
                exp_sum += expf(s_j - max_score);
            }

            attn_weight /= exp_sum;

            // Multiply by value and accumulate
            int value_offset = b * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + k_pos * head_dim + dim;
            sum += attn_weight * value[value_offset];
        }

        // Write output
        int out_offset = b * num_heads * seq_len * head_dim + head * seq_len * head_dim + pos * head_dim + dim;
        output[out_offset] = sum;
    }
}

torch::Tensor gqa_attention_hip(
    torch::Tensor query,
    torch::Tensor key,
    torch::Tensor value,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    float scale
) {
    auto batch_size = query.size(0);

    // Reshape input: (batch, num_heads, seq_len, head_dim)
    query = query.contiguous();
    key = key.contiguous();
    value = value.contiguous();

    // Allocate output
    auto output = torch::zeros({batch_size, num_heads, seq_len, head_dim}, query.options());

    const int num_key_value_groups = num_heads / num_kv_heads;

    // Launch kernel
    // Each block handles one (head, batch, position)
    int num_blocks = num_heads * batch_size * seq_len;
    int block_size = 256;

    gqa_attention_kernel<<<num_blocks, block_size, head_dim * sizeof(float)>>>(
        query.data_ptr<float>(),
        key.data_ptr<float>(),
        value.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_heads,
        num_kv_heads,
        seq_len,
        head_dim,
        num_key_value_groups,
        scale
    );

    return output;
}
"""

gqa_attention_lib = load_inline(
    name="gqa_attention",
