gated_delta_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gated_delta_stateful_kernel(
    const float* q_ptr,
    const float* k_ptr,
    const float* v_ptr,
    const float* alpha_ptr,
    const float* beta_ptr,
    float* o_ptr,
    int batch_size, int seq_len, int num_heads, int head_dim_qk, int head_dim_v) {

    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) {
        return;
    }

    // Shared memory: S matrix + error + k + v vectors
    extern __shared__ float shared_mem[];
    float* S = shared_mem;
    float* error = S + head_dim_v * head_dim_qk;
    float* k_vec = error + head_dim_v;
    float* v_vec = k_vec + head_dim_qk;

    // Initialize S to zero
    int S_size = head_dim_v * head_dim_qk;
    #pragma unroll
    for (int i = threadIdx.x; i < S_size; i += blockDim.x) {
        S[i] = 0.0f;
    }

    int q_stride = num_heads * head_dim_qk;
    int k_stride = num_heads * head_dim_qk;
    int v_stride = num_heads * head_dim_v;
    int alpha_stride = num_heads;
    int beta_stride = num_heads;
    int o_stride = num_heads * head_dim_v;

    // Loop over sequence
    for (int t = 0; t < seq_len; t++) {
        // Load k_t, v_t into shared memory
        int k_offset = batch_idx * seq_len * k_stride + t * k_stride + head_idx * head_dim_qk;
        int v_offset = batch_idx * seq_len * v_stride + t * v_stride + head_idx * head_dim_v;

        #pragma unroll
        for (int i = threadIdx.x; i < head_dim_qk; i += blockDim.x) {
            k_vec[i] = k_ptr[k_offset + i];
        }
        #pragma unroll
        for (int i = threadIdx.x; i < head_dim_v; i += blockDim.x) {
            v_vec[i] = v_ptr[v_offset + i];
        }

        __syncthreads();

        // Load alpha_t, beta_t
        int alpha_beta_offset = batch_idx * seq_len * alpha_stride + t * alpha_stride + head_idx;
        float alpha_t = alpha_ptr[alpha_beta_offset];
        float beta_t = beta_ptr[alpha_beta_offset];

        // Compute S_k = S @ k_t: (head_dim_v,) 
        // Each thread handles one element
        float S_k_local = 0.0f;
        if (threadIdx.x < head_dim_v) {
            int row_offset = threadIdx.x * head_dim_qk;
            for (int j = 0; j < head_dim_qk; j++) {
                S_k_local += S[row_offset + j] * k_vec[j];
            }
        }

        __syncthreads();

        // Compute error = S_k - v and store in shared memory
        if (threadIdx.x < head_dim_v) {
            error[threadIdx.x] = S_k_local - v_vec[threadIdx.x];
        }

        __syncthreads();

        // Compute S = alpha * S - beta * error @ k^T
        #pragma unroll
        for (int i = threadIdx.x; i < S_size; i += blockDim.x) {
            int row = i / head_dim_qk;
            int col = i % head_dim_qk;
            float outer_product = error[row] * k_vec[col];  // Correct indexing!
            S[i] = alpha_t * S[i] - beta_t * outer_product;
        }

        __syncthreads();

        // Compute o_t = S @ q_t
        float o_local = 0.0f;
        if (threadIdx.x < head_dim_v) {
            int q_offset = batch_idx * seq_len * q_stride + t * q_stride + head_idx * head_dim_qk;
            int row_offset = threadIdx.x * head_dim_qk;
            for (int j = 0; j < head_dim_qk; j++) {
                o_local += S[row_offset + j] * q_ptr[q_offset + j];
            }
        }

        // Write output
        if (threadIdx.x < head_dim_v) {
            int o_offset = batch_idx * seq_len * o_stride + t * o_stride + head_idx * head_dim_v + threadIdx.x;
            o_ptr[o_offset] = o_local;
        }

        __syncthreads();
    }
}

torch::Tensor gated_delta_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v,
    torch::Tensor alpha, torch::Tensor beta,
    int num_heads, int head_dim_qk, int head_dim_v) {

    int batch_size = q.size(0);
    int seq_len = q.size(1);

    auto o = torch::zeros_like(v);

    int shared_mem_size = (head_dim_v * head_dim_qk + head_dim_v + head_dim_qk + head_dim_v) * sizeof(float);
    int threads_per_block = 256;

    dim3 grid(batch_size, num_heads);
    dim3 block(threads_per_block);

    gated_delta_stateful_kernel<<<grid, block, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        alpha.data_ptr<float>(),
        beta.data_ptr<float>(),
        o.data_ptr<float>(),
        batch_size, seq_len, num_heads, head_dim_qk, head_dim_v
    );

    return o;
}
"""

gated_delta_lib = load_inline(
