repeat_kv_source = """
#include <hip/hip_runtime.h>

// Kernel to expand KV heads to match query heads efficiently
// Instead of creating a new expanded tensor, this computes the mapping on-the-fly
// However, for simplicity and correctness, we'll just use a more efficient repeat operation
__global__ void repeat_kv_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int num_kv_heads,
    const int n_rep,
    const int seq_len,
    const int head_dim
) {
    int batch = blockIdx.z;
    int out_head = blockIdx.y;
    int pos = blockIdx.x;
    int dim = threadIdx.x;

    // Map output head to kv head
    int kv_head = out_head / n_rep;

    if (dim >= head_dim) return;

    int in_idx = batch * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + pos * head_dim + dim;
    int out_idx = batch * (num_kv_heads * n_rep) * seq_len * head_dim + out_head * seq_len * head_dim + pos * head_dim + dim;

    output[out_idx] = input[in_idx];
}

torch::Tensor repeat_kv_hip(
    torch::Tensor hidden_states,
    int n_rep
) {
    auto batch = hidden_states.size(0);
    auto num_kv_heads = hidden_states.size(1);
    auto seq_len = hidden_states.size(2);
    auto head_dim = hidden_states.size(3);

    if (n_rep == 1) {
        return hidden_states;
    }

    auto output = torch::zeros({batch, num_kv_heads * n_rep, seq_len, head_dim}, hidden_states.options());

    dim3 block_dim(head_dim);
    dim3 grid_dim(seq_len, num_kv_heads * n_rep, batch);

    repeat_kv_kernel<<<grid_dim, block_dim>>>(
        hidden_states.data_ptr<float>(),
        output.data_ptr<float>(),
        batch,
        num_kv_heads,
        n_rep,
        seq_len,
        head_dim
    );

    return output;
}
"""

