# Fused Gated Dual GEMM kernel
# Computes: output = down_proj(SiLU(gate_proj(x)) * up_proj(x))
# Uses parallel processing across threads

gateld_gemm_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 256

__global__ void gated_dual_gemm_kernel(
    const float* x,          // (num_tokens, hidden_size)
    const float* gate_proj,  // (intermediate_size, hidden_size)
    const float* up_proj,    // (intermediate_size, hidden_size)
    const float* down_proj,  // (hidden_size, intermediate_size)
    float* output,           // (num_tokens, hidden_size)
    int num_tokens,
    int hidden_size,
    int intermediate_size
) {
    // Each thread block processes one token
    int token_idx = blockIdx.x;
    if (token_idx >= num_tokens) return;

    int thread_idx = threadIdx.x;

    // Shared memory for storing gate and up results
    __shared__ float gate_shared[BLOCK_SIZE];
    __shared__ float up_shared[BLOCK_SIZE];

    const float* x_ptr = x + token_idx * hidden_size;

    // Split intermediate_size computation across threads
    for (int im_base = 0; im_base < intermediate_size; im_base += BLOCK_SIZE) {
        int im_idx = im_base + thread_idx;

        // Each thread computes one dimension of gate and up
        if (im_idx < intermediate_size) {
            float gate_val = 0.0f;
            float up_val = 0.0f;

            const float* gate_w = gate_proj + im_idx * hidden_size;
            const float* up_w = up_proj + im_idx * hidden_size;

            // Compute dot products
            #pragma unroll 4
            for (int h = 0; h < hidden_size; h++) {
                float x_val = x_ptr[h];
                gate_val += x_val * gate_w[h];
                up_val += x_val * up_w[h];
            }

            gate_shared[thread_idx] = gate_val;
            up_shared[thread_idx] = up_val;

            // Compute this thread's contribution to all output dimensions
            // Split hidden_size computation across threads
            int h_idx_start = (hidden_size * thread_idx) / blockDim.x;
            int h_idx_end = (hidden_size * (thread_idx + 1)) / blockDim.x;

            for (int h_idx = h_idx_start; h_idx < h_idx_end; h_idx++) {
                const float* down_w = down_proj + h_idx * intermediate_size;
                float silu_gate = gate_val / (1.0f + expf(-gate_val));
                float elem_mul = silu_gate * up_val;
                float contrib = elem_mul * down_w[im_idx];

                if (im_base == 0 && thread_idx == 0) {
                    output[token_idx * hidden_size + h_idx] = contrib;
                } else if (im_base == 0) {
                    output[token_idx * hidden_size + h_idx] = contrib;
                } else {
                    atomicAdd(&output[token_idx * hidden_size + h_idx], contrib);
                }
            }
        }
    }
}

torch::Tensor gated_dual_gemm_hip(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj
) {
    int num_tokens = x.size(0);
    int hidden_size = x.size(1);
    int intermediate_size = gate_proj.size(0);

    // Initialize output to zero
    auto output = torch::zeros_like(x);

    // Use parallel threads
    dim3 grid(num_tokens);
    dim3 blocks(BLOCK_SIZE);

    gated_dual_gemm_kernel<<<grid, blocks>>>(
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        hidden_size,
        intermediate_size
    );

    return output;
}
"""

gated_dual_gemm = load_inline(
    name="gated_dual_gemm",
    cpp_sources=gateld_gemm_cpp_source,
    functions=["gated_dual_gemm_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized MoE Expert with Gated GEMM (SiLU-gated FFN).

    Key optimizations:
    1. FUSED GATED DUAL GEMM KERNEL: gate_proj, up_proj, SiLU, multiply, and down_proj
       are combined into a single kernel that reads x once
    2. Parallel processing across threads for faster computation
    3. Fuses activation (SiLU) with the multiplication step
    """

    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        # Expert weights
        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gated_dual_gemm = gated_dual_gemm

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        batch, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]

        # Reshape for processing
        x_flat = x.view(-1, self.hidden_size)
        num_tokens = x_flat.shape[0]

        # Initialize output accumulator
        output = torch.zeros(num_tokens, self.hidden_size, device=x.device, dtype=x.dtype)

        # Process each expert
        for expert_idx in range(self.num_experts):
            # Find which (token, slot) pairs use this expert
            expert_mask = (expert_indices == expert_idx)

            if not expert_mask.any():
                continue

            # Get token indices and their routing weights
            batch_idx, seq_idx, slot_idx = torch.where(expert_mask)
            token_indices = batch_idx * seq_len + seq_idx
            weights = expert_weights[batch_idx, seq_idx, slot_idx]

            # Get tokens for this expert
            expert_input = x_flat[token_indices]

            # OPTIMIZED: Use fused gated dual GEMM kernel
            expert_output = self.gated_dual_gemm.gated_dual_gemm_hip(
                expert_input,
                self.gate_proj[expert_idx],
                self.up_proj[expert_idx],
                self.down_proj[expert_idx]
            )

            # Accumulate weighted output
            output.index_add_(0, token_indices, expert_output * weights.unsqueeze(-1))

        return output.view(batch, seq_len, self.hidden_size)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

gated_delta_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gated_delta_stateful_kernel(
    const float* q_ptr,
    const float* k_ptr,
    const float* v_ptr,
    const float* alpha_ptr,
    const float* beta_ptr,
    float* o_ptr,
    int batch_size, int seq_len, int num_heads, int head_dim_qk, int head_dim_v) {

    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) {
        return;
    }

    extern __shared__ float shared_mem[];
    float* S = shared_mem;
    float* k_vec = S + head_dim_v * head_dim_qk;
    float* v_vec = k_vec + head_dim_qk;

    // Initialize S to zero
    int S_size = head_dim_v * head_dim_qk;
    #pragma unroll
    for (int i = threadIdx.x; i < S_size; i += blockDim.x) {
        S[i] = 0.0f;
    }

    int q_stride = num_heads * head_dim_qk;
    int k_stride = num_heads * head_dim_qk;
    int v_stride = num_heads * head_dim_v;
    int alpha_stride = num_heads;
    int beta_stride = num_heads;
    int o_stride = num_heads * head_dim_v;

    // Loop over sequence
    for (int t = 0; t < seq_len; t++) {
        // Load k_t, v_t into shared memory
        int k_offset = batch_idx * seq_len * k_stride + t * k_stride + head_idx * head_dim_qk;
        int v_offset = batch_idx * seq_len * v_stride + t * v_stride + head_idx * head_dim_v;

        #pragma unroll
        for (int i = threadIdx.x; i < head_dim_qk; i += blockDim.x) {
            k_vec[i] = k_ptr[k_offset + i];
        }
        #pragma unroll
        for (int i = threadIdx.x; i < head_dim_v; i += blockDim.x) {
            v_vec[i] = v_ptr[v_offset + i];
        }

        __syncthreads();

        // Load alpha_t, beta_t
        int alpha_beta_offset = batch_idx * seq_len * alpha_stride + t * alpha_stride + head_idx;
        float alpha_t = alpha_ptr[alpha_beta_offset];
        float beta_t = beta_ptr[alpha_beta_offset];

        // Compute S_k = S @ k_t and store in registers, one per thread for head_dim_v threads
        float S_k_local = 0.0f;
        if (threadIdx.x < head_dim_v) {
            int row_offset = threadIdx.x * head_dim_qk;
            for (int j = 0; j < head_dim_qk; j++) {
                S_k_local += S[row_offset + j] * k_vec[j];
            }
        }

        __syncthreads();

        // Compute error = S_k - v and write back to S start, then sync
        float error_local = 0.0f;
        if (threadIdx.x < head_dim_v) {
            error_local = S_k_local - v_vec[threadIdx.x];
        }

        __syncthreads();

        if (threadIdx.x < head_dim_v) {
            S[threadIdx.x] = error_local;  // Store error at start of shared memory temporarily
        }
        float* error_vec = S;  // Use beginning of S as error vector storage

        __syncthreads();

        // Compute S = alpha * S - beta * error @ k^T
        // Need all threads to update S
        for (int i = threadIdx.x; i < S_size; i += blockDim.x) {
            int row = i / head_dim_qk;
            int col = i % head_dim_qk;
            float outer_product = error_vec[row] * k_vec[col];
            S[i] = alpha_t * S[i] - beta_t * outer_product;
        }
        // Restore S from overlap with error

        __syncthreads();

        // Compute o_t = S @ q_t
        float o_local = 0.0f;
        if (threadIdx.x < head_dim_v) {
            int q_offset = batch_idx * seq_len * q_stride + t * q_stride + head_idx * head_dim_qk;
            int row_offset = threadIdx.x * head_dim_qk;
            for (int j = 0; j < head_dim_qk; j++) {
                o_local += S[row_offset + j] * q_ptr[q_offset + j];
            }

            int o_offset = batch_idx * seq_len * o_stride + t * o_stride + head_idx * head_dim_v + threadIdx.x;
            o_ptr[o_offset] = o_local;
        }

        __syncthreads();
    }
}

torch::Tensor gated_delta_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v,
    torch::Tensor alpha, torch::Tensor beta,
    int num_heads, int head_dim_qk, int head_dim_v) {

    int batch_size = q.size(0);
    int seq_len = q.size(1);

    auto o = torch::zeros_like(v);

    int shared_mem_size = (head_dim_v * head_dim_qk + head_dim_qk + head_dim_v) * sizeof(float);
    int threads_per_block = 256;

    dim3 grid(batch_size, num_heads);
    dim3 block(threads_per_block);

    gated_delta_stateful_kernel<<<grid, block, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        alpha.data_ptr<float>(),
        beta.data_ptr<float>(),
        o.data_ptr<float>(),
        batch_size, seq_len, num_heads, head_dim_qk, head_dim_v
    );

    return o;
}
"""

gated_delta_lib = load_inline(
