        }

        __syncthreads();

        // Compute S = alpha * S - beta * error @ k^T
        // All threads participate in updating S
        #pragma unroll
        for (int i = threadIdx.x; i < S_size; i += blockDim.x) {
            int row = i / head_dim_qk;
            int col = i % head_dim_qk;
            float outer_product = error_vec[row] * k_vec[col];
