# Optimized element-wise multiply with SiLU kernel
# Fuses: silu(a) * b into a single kernel

fused_silu_mul_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void fused_silu_mul_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float a_val = a[idx];
        // SiLU: f(x) = x * sigmoid(x) = x / (1 + exp(-x))
        float silu = a_val / (1.0f + expf(-a_val));
        out[idx] = silu * b[idx];
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor a, torch::Tensor b) {
    int size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_silu_mul_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

fused_silu_mul = load_inline(
    name="fused_silu_mul",
    cpp_sources=fused_silu_mul_cpp_source,
    functions=["fused_silu_mul_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized MoE Expert with Gated GEMM (SiLU-gated FFN).

    Key optimizations:
    1. Fused SiLU + elementwise multiply kernel to reduce kernel launch overhead
    2. This reduces the number of kernel launches from 2 to 1 for the gating operation
    """

    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        # Expert weights
        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.fused_silu_mul = fused_silu_mul

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        """
        MoE forward with optimized fused SiLU + multiply kernel.
        """
        batch, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]

        # Reshape for processing
        x_flat = x.view(-1, self.hidden_size)
        num_tokens = x_flat.shape[0]

        # Initialize output accumulator
        output = torch.zeros(num_tokens, self.hidden_size, device=x.device, dtype=x.dtype)

        # Process each expert
        for expert_idx in range(self.num_experts):
            # Find which (token, slot) pairs use this expert
            expert_mask = (expert_indices == expert_idx)

            if not expert_mask.any():
                continue

            # Get token indices and their routing weights
            batch_idx, seq_idx, slot_idx = torch.where(expert_mask)
            token_indices = batch_idx * seq_len + seq_idx
            weights = expert_weights[batch_idx, seq_idx, slot_idx]

            # Get tokens for this expert
            expert_input = x_flat[token_indices]

            # Compute gate and up projections
            gate = F.linear(expert_input, self.gate_proj[expert_idx])
            up = F.linear(expert_input, self.up_proj[expert_idx])

            # OPTIMIZED: Use fused SiLU + multiply kernel
            intermediate = self.fused_silu_mul.fused_silu_mul_hip(gate, up)

            expert_output = F.linear(intermediate, self.down_proj[expert_idx])

            # Accumulate weighted output
            output.index_add_(0, token_indices, expert_output * weights.unsqueeze(-1))

        return output.view(batch, seq_len, self.hidden_size)

