# Optimized kernel for applying rotary positional embeddings
rope_source = """
#include <hip/hip_runtime.h>

// Kernel to apply rotary positional embeddings to query and key
// Fuses the rotate half and cosine/sine multiplication operations
__global__ void apply_rope_kernel(
    const float* __restrict__ q_input,
    const float* __restrict__ k_input,
    float* __restrict__ q_output,
    float* __restrict__ k_output,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    const int batch_size,
    const int num_heads,
    const int seq_len,
    const int head_dim
) {
    int batch = blockIdx.z;
    int head = blockIdx.y;
    int pos = blockIdx.x;

    int half_dim = head_dim / 2;
    int tid = threadIdx.x;

    // Process pairs of elements (for rotate half)
    int i = tid;

    // Compute linear offsets
    int base_offset = batch * num_heads * seq_len * head_dim + head * seq_len * head_dim + pos * head_dim;

    // Get cos and sin for this position
    float c = cos[pos];
    float s = sin[pos];

    // Process first half
    if (i < half_dim) {
        int idx = base_offset + i;
        int idx2 = base_offset + i + half_dim;

        // For query
        float q1 = q_input[idx];
        float q2 = q_input[idx2];
        q_output[idx] = q1 * c + q2 * s;    // q*cos + rotate_half(q)*sin where rotate_half = (-x2, x1), x1=x2, x2=-x1 => q1*c + (-q2)*s = q1*c - q2*s? No
        // rotate_half: (-x2, x1), so q_embed = q*cos + (-q2, q1)*sin
        // First half: q1*cos + (-q2)*sin
        // Second half: q2*cos + q1*sin
        float q_out1 = q1 * c - q2 * s;
        float q_out2 = q1 * s + q2 * c;

        // Wait, let's recalculate: rotate_half(x) where x = [x1, x2] gives [-x2, x1]
        // q_embed = q * cos + rotate_half(q) * sin
        // First element: q1*cos + (-q2)*sin
        // Second element: q2*cos + q1*sin

        q_output[idx] = q1 * c - q2 * s;
        q_output[idx2] = q1 * s + q2 * c;

        // For key
        float k1 = k_input[idx];
        float k2 = k_input[idx2];
        k_output[idx] = k1 * c - k2 * s;
        k_output[idx2] = k1 * s + k2 * c;
    }
}

torch::Tensor apply_rope_hip(
    torch::Tensor query,
    torch::Tensor key,
    torch::Tensor cos,
    torch::Tensor sin
) {
    auto batch = query.size(0);
    auto num_heads = query.size(1);
    auto seq_len = query.size(2);
    auto head_dim = query.size(3);

    auto q_output = torch::empty_like(query);
    auto k_output = torch::empty_like(key);

    cos = cos.squeeze().squeeze();  // remove batch and head dims
    sin = sin.squeeze().squeeze();

    int block_size = 256;
    int half_dim = (head_dim + 1) / 2;

    dim3 block_dim(block_size, 1, 1);
    dim3 grid_dim(seq_len, num_heads, batch);

    apply_rope_kernel<<<grid_dim, block_dim>>>(
        query.data_ptr<float>(),
        key.data_ptr<float>(),
        q_output.data_ptr<float>(),
        k_output.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        batch,
        num_heads,
        seq_len,
        head_dim
    );

    return q_output, k_output;
}
"""

rope_lib = load_inline(
    name="rope_lib",
    cpp_sources=rope_source,
