        S.data_ptr<float>(), k_t.data_ptr<float>(), v_t.data_ptr<float>(),
        a_t.data_ptr<float>(), q_t.data_ptr<float>(), beta.data_ptr<float>(),
        S_out.data_ptr<float>(), o_t.data_ptr<float>(),
        batch_size, num_heads, head_dim_v, head_dim_qk
