# Optimized kernel for GQA attention that avoids explicit KV expansion
# Computes attention scores and output with implicit KV head repetition
gqa_qk_source = """
#include <hip/hip_runtime.h>

// Kernel to compute QK^T with implicit KV head repetition
// Avoids expanding K tensors by computing which query heads share which KV heads
__global__ void gqa_qk_kernel(
    const float* __restrict__ query,
    const float* __restrict__ key,
    float* __restrict__ attn_weights,
    const int batch_size,
    const int num_heads,
    const int num_kv_heads,
    const int seq_len,
    const int head_dim,
    const float scale
) {
    int batch = blockIdx.z;
    int head = blockIdx.y;
    int pos = blockIdx.x;
    int dim = threadIdx.x;

    // Map query head to kv head
    int kv_head = head / (num_heads / num_kv_heads);

    // Each thread block computes dot products for its (batch, head, pos)
    extern __shared__ float shmem[];

    // Shared memory for query vector and partial sums
    float* query_vec = shmem;
    float* dot_products = shmem + head_dim;

    // Load query vector
    query_vec[dim] = 0.0f;
    if (dim < head_dim) {
        int q_offset = batch * num_heads * seq_len * head_dim + head * seq_len * head_dim + pos * head_dim + dim;
        query_vec[dim] = query[q_offset];
    }

    // Initialize dot products
    for (int d = dim; d < seq_len; d += blockDim.x) {
        dot_products[d] = 0.0f;
    }
    __syncthreads();

    // Compute dot products for all positions
    for (int d = dim; d < head_dim; d += blockDim.x) {
        if (d < head_dim) {
            float q_val = query_vec[d];
            for (int k_pos = 0; k_pos < seq_len; k_pos++) {
                int k_offset = batch * num_kv_heads * seq_len * head_dim + kv_head * seq_len * head_dim + k_pos * head_dim + d;
                float k_val = key[k_offset];
                // Atomic add since multiple threads might be updating same position
                atomicAdd(&dot_products[k_pos], q_val * k_val);
            }
        }
    }
    __syncthreads();

    // Store scaled dot products
    for (int d = dim; d < seq_len; d += blockDim.x) {
        attn_weights[batch * num_heads * seq_len * seq_len + head * seq_len * seq_len + pos * seq_len + d] = dot_products[d] * scale;
    }
}

torch::Tensor gqa_qk_hip(
    torch::Tensor query,
    torch::Tensor key,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    float scale
) {
    auto batch_size = query.size(0);

    auto attn_weights = torch::zeros({batch_size, num_heads, seq_len, seq_len}, query.options());

    int block_size = 256;
    dim3 grid_dim(seq_len, num_heads, batch_size);

    int shmem_size = (head_dim + seq_len) * sizeof(float);

    gqa_qk_kernel<<<grid_dim, block_size, shmem_size>>>(
        query.data_ptr<float>(),
        key.data_ptr<float>(),
        attn_weights.data_ptr<float>(),
        batch_size,
        num_heads,
        num_kv_heads,
        seq_len,
        head_dim,
        scale
    );

    return attn_weights;
}
"""

